package com.nexodb.ui;

import com.formdev.flatlaf.FlatDarkLaf;
import com.nexodb.db.JdbcSession;
import com.nexodb.model.*;
import javax.swing.*;
import java.lang.reflect.Field;
import java.nio.file.Path;
import java.time.Duration;
import java.util.concurrent.atomic.AtomicBoolean;

public final class DataQualityPanelTest {
    public static void main(String[] args)throws Exception{
        FlatDarkLaf.setup();ConnectionProfile profile=new ConnectionProfile("quality-panel","Quality H2",DatabaseType.H2,"",0,"mem:quality-panel","sa","jdbc:h2:mem:quality-panel;DB_CLOSE_DELAY=-1","org.h2.Driver",Path.of("build/h2-test.jar").toAbsolutePath().toString(),false);
        try(JdbcSession session=JdbcSession.open(profile,new char[0])){session.execute("CREATE TABLE customers(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(80),email VARCHAR(120))",10);DataQualityPanel[] panel=new DataQualityPanel[1];SwingUtilities.invokeAndWait(()->panel[0]=new DataQualityPanel(session,"PUBLIC"));await(()->field(panel[0],"current")!=null);JTabbedPane tabs=find(panel[0],JTabbedPane.class);equal(3,tabs.getTabCount());JComboBox<?> tables=typedField(panel[0],"tables",JComboBox.class);require(tables.getItemCount()==1,"Table selector did not load");JButton apply=typedField(panel[0],"applyMask",JButton.class);require(!apply.isEnabled(),"Masking should require a preview");require(panel[0].getBackground()!=null,"Dark background missing");}
        System.out.println("DataQualityPanelTest: OK (dark UI, asynchronous table selection, three safe workflows and preview gate)");
    }
    private static void await(Check check)throws Exception{long end=System.nanoTime()+Duration.ofSeconds(10).toNanos();while(System.nanoTime()<end){AtomicBoolean done=new AtomicBoolean();SwingUtilities.invokeAndWait(()->done.set(check.ok()));if(done.get())return;Thread.sleep(25);}throw new AssertionError("Timed out");}
    private interface Check{boolean ok();}
    private static Object field(Object target,String name){try{Field field=target.getClass().getDeclaredField(name);field.setAccessible(true);return field.get(target);}catch(Exception error){throw new RuntimeException(error);}}
    private static <T>T typedField(Object target,String name,Class<T> type){return type.cast(field(target,name));}
    private static <T>T find(java.awt.Container root,Class<T> type){for(java.awt.Component child:root.getComponents()){if(type.isInstance(child))return type.cast(child);if(child instanceof java.awt.Container nested){T found=find(nested,type);if(found!=null)return found;}}return null;}
    private static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
    private static void equal(Object expected,Object actual){if(!java.util.Objects.equals(expected,actual))throw new AssertionError("Expected ["+expected+"] got ["+actual+"]");}
}
